// Differential probe for the native JSNumberMath exponential/logarithm entry points added on
// top of the pinned Node/V8 fdlibm port: Math.exp, Math.log and Math.log2.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-math-exp-log.mjs, which replays the same calls against the global Math
// object of the pinned Node release, so the field order below is the single source of truth
// for both sides.
//
//   exp <x>         Math.exp(x)
//   log <x>         Math.log(x)
//   log2 <x>        Math.log2(x)
//   lcg <count>     the shared 32-bit LCG sequence rendered as doubles
//   bits <count>    the shared 32-bit LCG pairs reinterpreted as raw doubles
//
// Numbers use the shared encoding of the other probes: NaN, -0, Infinity and -Infinity
// travel as those four strings. `lcg` and `bits` exist so the generator and the probe are
// shown to walk the same pseudo-random inputs before those inputs are reused as the grid:
// `lcg` renders the state as a double, `bits` packs two states into the raw bit pattern of a
// double so that subnormals, huge values and NaN bit patterns are all reached.
#include "core/JsonValue.h"
#include "math/JSNumberMath.h"
#include <bit>
#include <charconv>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>

namespace {

JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}

// The generator walks this sequence with Math.imul and the same constants, and the `lcg` and
// `bits` scenarios compare the two runs before they continue into the grids below.
std::uint32_t lcgState = 0x2545F491u;
std::uint32_t lcgNext() {
    lcgState = lcgState * 1664525u + 1013904223u;
    return lcgState;
}
double lcgDouble() {
    const std::uint32_t bits = lcgNext();
    const double sign = (bits & 1u) == 1u ? -1. : 1.;
    const int exponent = static_cast<int>((bits >> 1) % 40u) - 20;
    const double mantissa = static_cast<double>(bits >> 7);
    // 1 + mantissa / 2^32 and 2^exponent are exact, so both languages land on the same
    // double without a rounding step either could disagree about.
    return sign * (1. + mantissa / 4294967296.) * std::ldexp(1., exponent);
}
// Two states of the same sequence become the high and the low word of a double, which the
// generator reproduces with a DataView and a BigInt.
double lcgBits() {
    const std::uint64_t high = lcgNext();
    const std::uint64_t low = lcgNext();
    return std::bit_cast<double>((high << 32) | low);
}

struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
};

JsonValue runScenario(const std::string& line) {
    Reader reader(line);
    const std::string kind = reader.token();

    if (kind == "exp") {
        return JsonValue::Object{{"value", number(JSNumberMath::exp(reader.numberToken()))}};
    }

    if (kind == "log") {
        return JsonValue::Object{{"value", number(JSNumberMath::log(reader.numberToken()))}};
    }

    if (kind == "log2") {
        return JsonValue::Object{{"value", number(JSNumberMath::log2(reader.numberToken()))}};
    }

    if (kind == "lcg") {
        const auto count = static_cast<std::size_t>(reader.numberToken());
        JsonValue::Array values;
        values.reserve(count);
        for (std::size_t i = 0; i < count; ++i) values.push_back(number(lcgDouble()));
        return JsonValue::Object{{"values", std::move(values)}};
    }

    if (kind == "bits") {
        const auto count = static_cast<std::size_t>(reader.numberToken());
        JsonValue::Array values;
        values.reserve(count);
        for (std::size_t i = 0; i < count; ++i) values.push_back(number(lcgBits()));
        return JsonValue::Object{{"values", std::move(values)}};
    }

    throw std::runtime_error("unknown scenario kind: " + kind);
}

} // namespace

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        try {
            std::cout << runScenario(line).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
